import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Reliability mechanisms","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/reliability.md","filePath":"en/modules/kits/reliability.md","lastUpdated":0}`),a={name:`en/modules/kits/reliability.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="reliability-mechanisms" tabindex="-1">Reliability mechanisms <a class="header-anchor" href="#reliability-mechanisms" aria-label="Permalink to “Reliability mechanisms”">​</a></h1><p>EmakiKits makes &quot;never double-grants, never loses records, survives a power cut&quot; checkable mechanisms: idempotency keys, audit records, atomic writes, and restart recovery. This page explains the mechanisms and gives demo steps any server owner can run</p><h2 id="idempotency-keys-against-double-claims" tabindex="-1">Idempotency keys against double claims <a class="header-anchor" href="#idempotency-keys-against-double-claims" aria-label="Permalink to “Idempotency keys against double claims”">​</a></h2><p>Every claim / redemption / purchase first registers an idempotency key; only a successful registration proceeds to delivery, and failed delivery rolls back:</p><table tabindex="0"><thead><tr><th>Key shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>claim|&lt;kit&gt;|&lt;player&gt;|&lt;period&gt;</code></td><td>Once per period for cyclic and one-shot kits</td></tr><tr><td><code>cdk_global|&lt;code&gt;</code></td><td><code>global_once</code> codes work once server-wide</td></tr><tr><td><code>cdk_player|&lt;code&gt;|&lt;player&gt;</code> and the CDK redemption counter</td><td><code>per_player_once</code> counted by <code>cdk.per_player_limit</code></td></tr><tr><td><code>bind|&lt;invitee&gt;</code></td><td>Invite binding</td></tr><tr><td><code>milestone|...</code> / <code>selection|...</code></td><td>Open milestones and choice records</td></tr></tbody></table><p>Duplicate claim / redemption attempts are rejected outright: the player gets the matching error text (such as <code>error.kit.already_claimed</code> or <code>error.cdk.exhausted</code>) and the console side also prints an anti-duplicate log line; nothing is silently swallowed</p><h2 id="audit-records" tabindex="-1">Audit records <a class="header-anchor" href="#audit-records" aria-label="Permalink to “Audit records”">​</a></h2><p>Every key action lands one audit entry (player, kit, action, transaction id, time):</p><ul><li><code>/ekits inspect &lt;player or UUID&gt;</code> shows a player&#39;s audit records, offline players included</li><li>Audits persist inside <code>data/store.yml</code>; the retention is controlled by <code>storage.retention.audit_days</code> (see <a href="./configuration.html">Configuration</a>)</li></ul><h2 id="atomic-writes" tabindex="-1">Atomic writes <a class="header-anchor" href="#atomic-writes" aria-label="Permalink to “Atomic writes”">​</a></h2><p><code>data/store.yml</code> is saved with tmp + move atomic replacement (<code>storage.atomic_writes: true</code>): the data is written to a temporary file first and swapped in whole, so a power cut in the middle never leaves half a file</p><h2 id="restart-recovery-demo" tabindex="-1">Restart recovery demo <a class="header-anchor" href="#restart-recovery-demo" aria-label="Permalink to “Restart recovery demo”">​</a></h2><ol><li>Claim a daily kit and confirm the audit entry with <code>/ekits inspect</code></li><li>Kill the server process outright (simulating a power cut); do not stop it normally</li><li>Restart and <code>/ekits claim</code> the same period again -&gt; it should be rejected (already claimed)</li><li><code>/ekits inspect</code> still shows the record, and <code>data/store.yml</code> parses cleanly</li></ol><p>If step 3 grants a second claim, that is a defect; please report it with <code>data/store.yml</code> and the console log</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};